/** Model-owned route construction: quadratic tangent bends, then length-domain cuts.
 * No upstream rendering/projection engine is used. Inputs retain the supplied endpoints. */
const add=(a,b)=>a.map((v,i)=>v+b[i]),sub=(a,b)=>a.map((v,i)=>v-b[i]),mul=(a,t)=>a.map(v=>v*t),mix=(a,b,t)=>add(a,mul(sub(b,a),t)),length=a=>Math.hypot(...a),unit=a=>mul(a,1/length(a));
export function bentRoute(points,radius=5.6){const result=[points[0]];for(let i=1;i<points.length-1;i++){const a=points[i-1],b=points[i],c=points[i+1],u=unit(sub(b,a)),v=unit(sub(c,b)),theta=Math.acos(Math.max(-1,Math.min(1,u.reduce((sum,x,j)=>sum+x*v[j],0)))),cut=Math.min(radius*Math.tan(theta/2),.48*Math.min(length(sub(b,a)),length(sub(c,b))));if(theta<.001){result.push(b);continue;}const p=sub(b,mul(u,cut)),q=add(b,mul(v,cut)),steps=Math.max(2,Math.ceil(12*theta/(Math.PI/2)));for(let j=0;j<=steps;j++){const t=j/steps;result.push(add(add(mul(p,(1-t)**2),mul(b,2*t*(1-t))),mul(q,t*t)));}}result.push(points.at(-1));return result;}
export const routeLength=points=>points.slice(1).reduce((s,p,i)=>s+length(sub(p,points[i])),0);
export function routeSlice(points,start,end){let walk=0;const out=[];for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],span=length(sub(b,a)),from=Math.max(start,walk),to=Math.min(end,walk+span);if(to>from){const p=mix(a,b,(from-walk)/span),q=mix(a,b,(to-walk)/span);if(!out.length||length(sub(p,out.at(-1)))>1e-8)out.push(p);out.push(q);}walk+=span;}if(out.length===2)out.splice(1,0,mix(out[0],out[1],.5));return out;}
export function distanceAtX(points,x){let walk=0;for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],span=length(sub(b,a));if((a[0]-x)*(b[0]-x)<=0&&Math.abs(b[0]-a[0])>1e-8)return walk+span*(x-a[0])/(b[0]-a[0]);walk+=span;}return null;}
